def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'D'

    op = [h[1] for h in history]
    op_def = op.count('D')

    if op_def == 0:
        return 'D'

    if n == 99:
        return 'D'

    consec_def = 0
    for a in reversed(op):
        if a == 'D':
            consec_def += 1
        else:
            break

    if consec_def >= 3:
        return 'D'

    return 'C'
